  1	\chapter{The Jacobian of a smooth proper curve}
  2	\label{chap:Challenge}
  3	
  4	Throughout, \(k\) is a field and \(C\) a \emph{smooth curve} over \(k\): a geometrically
  5	irreducible, smooth \(k\)-scheme of relative dimension one, proper over \(k\). We write
  6	\(C \to \Spec k\) for its structure morphism. This chapter states the goal of the project — the
  7	genus, the Jacobian, the Abel--Jacobi map, and the universal property that characterizes the
  8	Jacobian as the Albanese variety of \(C\). It is the mathematical counterpart of the statement file
  9	\texttt{AlgebraicJacobian/Challenge.lean}.
 10	
 11	\emph{Provenance.} Each node below should carry a \verb!\source{...}! anchor to the reference it is
 12	read from once that reference has been consulted; anchors are added during the rebuild, never
 13	guessed.
 14	
 15	\section{Genus}
 16	
 17	\begin{definition}[Genus]
 18	  \label{def:genus}
 19	  \lean{AlgebraicGeometry.genus}
 20	  \leanok
 21	  \uses{def:moduleKSheaf, def:HModule}
 22	  The \emph{genus} of a smooth proper curve \(C\) over \(k\) is
 23	  \[
 24	    g(C) \;=\; \dim_k H^1\!\bigl(C, \struct C\bigr),
 25	  \]
 26	  the \(k\)-dimension of the first cohomology group of the structure sheaf, viewed as a sheaf
 27	  of \(k\)-modules on the small Zariski site of \(C\) (Definition~\ref{def:moduleKSheaf}),
 28	  with cohomology the \(\Ext\)-groups from the constant sheaf
 29	  (Definition~\ref{def:HModule}).
 30	\end{definition}
 31	
 32	\section{The Jacobian as an abelian variety}
 33	
 34	\begin{definition}[Jacobian]
 35	  \label{def:jacobian}
 36	  \lean{AlgebraicGeometry.Jacobian}
 37	  The \emph{Jacobian} \(\Jac(C)\) of a smooth proper curve \(C\) over \(k\) is the identity
 38	  component \(\Pic^0_{C/k}\) of the relative Picard scheme of \(C\) over \(k\): the \(k\)-scheme
 39	  representing (the fppf-sheafification of) the functor of degree-zero line bundles on \(C\).
 40	\end{definition}
 41	
 42	\begin{proposition}[Group scheme structure]
 43	  \label{prop:jacobian_grpobj}
 44	  \uses{def:jacobian}
 45	  \lean{AlgebraicGeometry.Jacobian.instGrpObj}
 46	  \(\Jac(C)\) is a commutative group scheme over \(k\), with multiplication induced by the tensor
 47	  product of line bundles.
 48	\end{proposition}
 49	
 50	\begin{theorem}[Smoothness of the Jacobian]
 51	  \label{thm:jacobian_smooth}
 52	  \uses{def:genus, def:jacobian}
 53	  \lean{AlgebraicGeometry.Jacobian.smoothOfRelativeDimension_genus}
 54	  \(\Jac(C)\) is smooth over \(k\) of relative dimension \(g(C)\).
 55	\end{theorem}
 56	
 57	\begin{theorem}[Properness of the Jacobian]
 58	  \label{thm:jacobian_proper}
 59	  \uses{def:jacobian}
 60	  \lean{AlgebraicGeometry.Jacobian.instIsProper}
 61	  \(\Jac(C)\) is proper over \(k\).
 62	\end{theorem}
 63	
 64	\begin{theorem}[Geometric irreducibility of the Jacobian]
 65	  \label{thm:jacobian_geomirred}
 66	  \uses{def:jacobian}
 67	  \lean{AlgebraicGeometry.Jacobian.instGeometricallyIrreducible}
 68	  \(\Jac(C)\) is geometrically irreducible over \(k\).
 69	\end{theorem}
 70	
 71	In particular \(\Jac(C)\) is an abelian variety over \(k\) of dimension \(g(C)\).
 72	
 73	\section{The Abel--Jacobi map and the universal property}
 74	
 75	\begin{definition}[Abel--Jacobi map]
 76	  \label{def:ofCurve}
 77	  \uses{def:jacobian}
 78	  \lean{AlgebraicGeometry.Jacobian.ofCurve}
 79	  For a \(k\)-rational point \(P : \Spec k \to C\), the \emph{Abel--Jacobi map}
 80	  \(\varphi_P : C \to \Jac(C)\) sends a point \(Q\) to the class of the line bundle
 81	  \(\struct C(Q - P)\).
 82	\end{definition}
 83	
 84	\begin{lemma}[Base point maps to the origin]
 85	  \label{lem:comp_ofCurve}
 86	  \uses{def:ofCurve, prop:jacobian_grpobj}
 87	  \lean{AlgebraicGeometry.Jacobian.comp_ofCurve}
 88	  The Abel--Jacobi map \(\varphi_P\) sends the base point \(P\) to the neutral element of
 89	  \(\Jac(C)\): \(\varphi_P \circ P = 0\).
 90	\end{lemma}
 91	
 92	\begin{theorem}[Universal property of the Jacobian]
 93	  \label{thm:exists_unique_ofCurve_comp}
 94	  \uses{def:ofCurve, lem:comp_ofCurve, prop:jacobian_grpobj}
 95	  \lean{AlgebraicGeometry.Jacobian.exists_unique_ofCurve_comp}
 96	  \(\Jac(C)\) is the Albanese variety of \(C\): for every abelian variety \(A\) over \(k\) and every
 97	  morphism \(f : C \to A\) with \(f \circ P = 0\), there is a unique homomorphism of group schemes
 98	  \(g : \Jac(C) \to A\) such that \(f = g \circ \varphi_P\).
 99	\end{theorem}
  1	\chapter{The Jacobian datum}
  2	\label{chap:Jacobian}
  3	
  4	Throughout this chapter \(k\) is a field and \(C\) is the challenge curve: a
  5	scheme over \(k\), proper, smooth of relative dimension one, and geometrically
  6	irreducible. The degree-zero relative Picard functor
  7	\(\Pic^0_{C/k} : \Over(\Spec k)^{\op} \to \mathrm{CommGrp}\) was constructed in
  8	\ref{def:pic0Functor}. This chapter introduces the \emph{Jacobian datum} --- a
  9	representing object for \(\Pic^0_{C/k}\) together with the certificates its
 10	construction provides --- and develops what follows formally from it: the
 11	group structure and universal property of the representing object, its
 12	uniqueness up to canonical isomorphism, separatedness (every group scheme over
 13	a field is separated), the homogeneity supplied by translations, and, given a
 14	proper irreducible \emph{Abel source} mapping onto it, properness and geometric
 15	irreducibility.
 16	
 17	\section{The representability datum}
 18	\label{sec:jacobian_datum}
 19	
 20	\begin{definition}[Jacobian datum]
 21	  \label{def:jacobian_data}
 22	  \lean{AlgebraicGeometry.JacobianData}
 23	  \uses{def:pic0Functor}
 24	  \leanok
 25	  A \emph{Jacobian datum} for \(C\) consists of:
 26	  \begin{enumerate}
 27	    \item a scheme \(J\) over \(k\);
 28	    \item a representation of the degree-zero relative Picard functor by
 29	      \(J\): a family of bijections
 30	      \(\Hom_{\Over(\Spec k)}(T, J) \cong \mathrm{pic}^0(C, T)\), natural in
 31	      the test object \(T\);
 32	    \item the certificate that the structure morphism of \(J\) is locally of
 33	      finite type;
 34	    \item the certificate that the structure morphism of \(J\) is
 35	      quasi-compact.
 36	  \end{enumerate}
 37	  The two certificates come from the construction of the representing object
 38	  and are carried as part of the datum rather than re-derived.
 39	\end{definition}
 40	
 41	\begin{definition}[The group structure of the representing object]
 42	  \label{def:jacobian_data_grp}
 43	  \lean{AlgebraicGeometry.JacobianData.grpObj}
 44	  \uses{def:jacobian_data, def:pic0Functor}
 45	  \leanok
 46	  For a Jacobian datum \(d\) with representing object \(J\), the scheme \(J\)
 47	  is a group object of \(\Over(\Spec k)\), with multiplication, unit and
 48	  inversion induced by the commutative-group structure of
 49	  \(\mathrm{pic}^0(C, -)\) through the representation.
 50	\end{definition}
 51	\begin{proof}
 52	  \leanok
 53	  Transport the group structure across the natural bijections of
 54	  \ref{def:jacobian_data}: each \(\Hom(T, J)\) becomes a group, naturally in
 55	  \(T\) --- precomposition with any \(T' \to T\) is a group homomorphism
 56	  because the restriction maps of \(\Pic^0_{C/k}\) are. By the Yoneda lemma the
 57	  natural transformation
 58	  \(\Hom(-, J) \times \Hom(-, J) \to \Hom(-, J)\) given by the pointwise
 59	  products is induced by a unique morphism \(\mu : J \otimes J \to J\), and
 60	  similarly for the unit \(1 \to J\) and the inversion \(J \to J\); the group
 61	  axioms hold for these morphisms because they hold pointwise on
 62	  \(T\)-points.
 63	\end{proof}
 64	
 65	\begin{lemma}[The universal property, consumer form]
 66	  \label{lem:jacobian_data_homEquiv}
 67	  \lean{AlgebraicGeometry.JacobianData.homEquiv,
 68	    AlgebraicGeometry.JacobianData.homEquiv_comp}
 69	  \uses{def:jacobian_data, def:pic0Functor}
 70	  \leanok
 71	  Let \(d\) be a Jacobian datum with representing object \(J\). For every test
 72	  object \(T\) there is a bijection
 73	  \[
 74	    \theta_T : \Hom_{\Over(\Spec k)}(T, J) \;\cong\; \mathrm{pic}^0(C, T),
 75	  \]
 76	  natural against restriction: for \(f : T' \to T\) and \(g : T \to J\),
 77	  \[
 78	    \theta_{T'}(g \circ f) \;=\; f^*\bigl(\theta_T(g)\bigr),
 79	  \]
 80	  where \(f^*\) is the restriction map of \(\Pic^0_{C/k}\)
 81	  (\ref{def:pic0Functor}).
 82	\end{lemma}
 83	\begin{proof}
 84	  \leanok
 85	  This is the representation carried by the datum (\ref{def:jacobian_data}),
 86	  with its naturality read element-wise.
 87	\end{proof}
 88	
 89	\begin{definition}[Uniqueness of the representing object up to canonical
 90	    isomorphism]
 91	  \label{def:jacobian_data_unique}
 92	  \lean{AlgebraicGeometry.JacobianData.uniqueUpToIso,
 93	    AlgebraicGeometry.JacobianData.homEquiv_uniqueUpToIso_hom}
 94	  \uses{def:jacobian_data, lem:jacobian_data_homEquiv}
 95	  \leanok
